SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='5af0e472-b799-5183-a5ce-14410848f3c0'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('ccd7e851-bc45-5ad5-8ce8-1fa92438a02b','a274a351-ee55-5638-8eeb-2b54f208269f')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='5af0e472-b799-5183-a5ce-14410848f3c0'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='5af0e472-b799-5183-a5ce-14410848f3c0'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('ccd7e851-bc45-5ad5-8ce8-1fa92438a02b','a274a351-ee55-5638-8eeb-2b54f208269f')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='5af0e472-b799-5183-a5ce-14410848f3c0'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
