  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-customer-14-changed-fingerprint' AND q.fingerprint='53e96ba2531145c07ecea884a27475e9ac1c01e3a5273861c1c069c0b2fe8cf0'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"customer-14-changed-fingerprint","status":"ok","value":{"customerProfileId":"5af0e472-b799-5183-a5ce-14410848f3c0","userId":"3458d5ab-0b54-570c-adc3-cb03289deac3","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"ccd7e851-bc45-5ad5-8ce8-1fa92438a02b","semanticKey":"customer-controls-customer-14-changed-fingerprint","fingerprint":"53e96ba2531145c07ecea884a27475e9ac1c01e3a5273861c1c069c0b2fe8cf0","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='85d323cc-08c6-550f-8f9c-9b5ebb5dfe5d' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='10d51788-a50c-5494-b34a-882ffc72a77e' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"5af0e472-b799-5183-a5ce-14410848f3c0"},"prior":null,"committed":{"id":"5af0e472-b799-5183-a5ce-14410848f3c0","userId":"3458d5ab-0b54-570c-adc3-cb03289deac3","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='5af0e472-b799-5183-a5ce-14410848f3c0' AND c.user_id='3458d5ab-0b54-570c-adc3-cb03289deac3' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
