   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='customer-14-changed-fingerprint' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='ed83df00-5fd9-5621-81cb-3304ec11c564' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"5af0e472-b799-5183-a5ce-14410848f3c0","userId":"3458d5ab-0b54-570c-adc3-cb03289deac3","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='0ba000c6-41e6-5360-a865-374cb05edae5' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"3458d5ab-0b54-570c-adc3-cb03289deac3","track":"customer","customerProfileId":"5af0e472-b799-5183-a5ce-14410848f3c0","sourceCreationRevision":"0","sourceCreationReceipt":"ccd7e851-bc45-5ad5-8ce8-1fa92438a02b","semanticKey":"customer_buyer_profile/5af0e472-b799-5183-a5ce-14410848f3c0/default-free-enrollment/v1"}'::jsonb)))=2));
